/** 
 * An an output, where the output is taken from a single column from the specified RecordReader / SequenceRecordReader The assumption is that the specified column contains integer values in range 0..numClasses-1; this integer will be converted to a one-hot representation (usually for classification)
 * @param readerName Name of the RecordReader / SequenceRecordReader
 * @param column index of the column
 * @param numClasses Number of classes
 */
public Builder addOutputOneHot(String readerName,int column,int numClasses){
  try {
    outputs.add(new SubsetDetails(readerName,false,true,numClasses,column,-1));
  } catch (UnsupportedOperationException e) {
    throw new RuntimeException("The outputs list does not support the add operation.", e);
  } catch (IllegalArgumentException e) {
    throw new RuntimeException("Invalid argument provided to SubsetDetails constructor.", e);
  }
  return this;
}
